/** The longest chorus cut the catalogue ships (see public/assets/music/choruses.json). */
export const MAX_CUT = 15.5;
/** The longest crossfade between two choruses; beyond this the mash-up gets muddy. */
export const CROSSFADE = 3;

/**
 * How many songs fit in the playlist for a night of `nightDuration` seconds.
 *
 * The night is split into equal slots, one per song, and each slot has to fit a complete chorus cut
 * plus the crossfade into the next one: a shorter slot fragments the chorus, which is exactly the
 * part the DJ mix is made of. With the shipped catalogue (cuts up to 15,5 s and a 3 s crossfade) a
 * five-minute night fits 16 songs, not 10.
 */
export function playlistCapacity(nightDuration: number, cut = MAX_CUT, fade = CROSSFADE) {
  if (!Number.isFinite(nightDuration) || !Number.isFinite(cut) || !Number.isFinite(fade)) return 0;
  if (nightDuration <= 0 || cut <= 0 || fade < 0) return 0;
  // A night shorter than one chorus still gets a song: the last one loops until closing time.
  return Math.max(1, Math.floor(nightDuration / (cut + fade)));
}

export const TRACKS: Track[] = raw.slice(0, 100).map((row, index) => {
 const [artist, title, year, region, style] = row;
 // Ogg/Opus: the masters are 16-bit WAV, but the app ships Opus (see tools/encode-music.mjs),
 // which is ~10x smaller and decodes natively in browsers and Android WebView.
 return {id:`track-${String(index + 1).padStart(3,'0')}`, artist, title, year, region, style, file:`/assets/music/track-${String(index + 1).padStart(3,'0')}.ogg`};
});
if (TRACKS.length !== 100) throw new Error(`La cabina necesita 100 temas y tiene ${TRACKS.length}`);
